INSERT  IGNORE INTO `wp_wfIssues` VALUES (26573,1697890310,1697890310,'new','skippedPaths',25,'6fd0d290b978eab8027e6b79501ac149','6fd0d290b978eab8027e6b79501ac149','','The option \"Scan files outside your WordPress installation\" is off by default, which means 7 paths and their file(s) will not be scanned for malware or unauthorized changes. To continue skipping these paths, you may ignore this issue. Or to start scanning them, enable the option and subsequent scans will include them. Some paths may not be necessary to scan, so this is optional. <a href=\"https://www.wordfence.com/help/?query=scan-result-skipped-paths\" target=\"_blank\" rel=\"noopener noreferrer\">Learn More<span class=\"screen-reader-text\"> (se abre en una nueva pestaña)</span></a><br><br>The paths skipped are /www/komeijuku.com.ar/htdocs/danketsushin, /www/komeijuku.com.ar/htdocs/examen, /www/komeijuku.com.ar/htdocs/fukushima, /www/komeijuku.com.ar/htdocs/images, /www/komeijuku.com.ar/htdocs/sanmarcossierras, /www/komeijuku.com.ar/htdocs/tora, and /www/komeijuku.com.ar/htdocs/zarate','a:0:{}'),(26574,1697890581,1697890581,'new','knownfile',75,'8668223b197a2370c6d5e1ec6886015d','9276e646c9bbbb9deb13ac444dc8d2a7','Archivo desconocido en el núcleo de WordPress: wp-admin/core','This file is in a WordPress core location but is not distributed with this version of WordPress. This scan often includes files left over from a previous WordPress version, but it may also find files added by another plugin, files added by your host, or malicious files added by an attacker. <a href=\"https://www.wordfence.com/help/?query=scan-result-unknown-file-in-wordpress-core\" target=\"_blank\" rel=\"noopener noreferrer\">Learn More<span class=\"screen-reader-text\"> (se abre en una nueva pestaña)</span></a>','a:6:{s:4:\"file\";s:13:\"wp-admin/core\";s:8:\"realFile\";s:42:\"/www/komeijuku.com.ar/htdocs/wp-admin/core\";s:5:\"cType\";s:4:\"core\";s:7:\"canDiff\";b:0;s:6:\"canFix\";b:0;s:9:\"canDelete\";b:1;}'),(26575,16978